package org.l2start.bots.director;

import java.io.InputStream;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.ArrayList;
import java.util.Collections;
import java.util.HashMap;
import java.util.List;
import java.util.Map;

import javax.xml.parsers.DocumentBuilderFactory;

import org.l2start.bots.api.Assignment;
import org.l2start.bots.api.Pos;
import org.w3c.dom.Document;
import org.w3c.dom.Element;
import org.w3c.dom.NodeList;

/**
 * Towns and hunting grounds of the whole world (data/world.xml, generated by tools/gen-world.py from the stock
 * spawns, zones and map regions). Read-only after loading; lookups by position through a coarse grid.
 */
public final class WorldCatalog {
    /** A town: TownZone polygon, level band, anchors (gk, shop, wh, trainer, restart). */
    public record Town(String id, String name, Pos center, int radius, int minLevel, int maxLevel, int[] polyX, int[] polyY, List<Assignment.Anchor> anchors) {
        public boolean contains(int x, int y) {
            boolean in = false;
            for (int i = 0, j = polyX.length - 1; i < polyX.length; j = i++) {
                if (((polyY[i] > y) != (polyY[j] > y)) && (x < ((((double) polyX[j] - polyX[i]) * (y - polyY[i])) / ((double) polyY[j] - polyY[i])) + polyX[i])) {
                    in = !in;
                }
            }
            return in;
        }

        public List<Pos> anchors(String kind) {
            final List<Pos> l = new ArrayList<>();
            for (Assignment.Anchor a : anchors) {
                if (a.kind().equals(kind)) {
                    l.add(a.pos());
                }
            }
            return l;
        }
    }

    /** A hunting ground: monster territories clustered; level = 10..90th percentile of its monsters. */
    public record Ground(String id, String town, Pos center, int radius, int minLevel, int maxLevel, int monsters, double aggressive, boolean indoor, List<Pos> spots) {
        public boolean fits(int level) {
            return (level >= (minLevel - 2)) && (level <= (maxLevel + 2));
        }
    }

    static final int CELL = 8192;

    private final List<Town> towns;
    private final List<Ground> grounds;
    private final Map<Long, List<Ground>> grid = new HashMap<>();
    private final Map<String, Town> townById = new HashMap<>();
    private final Map<String, Ground> groundById = new HashMap<>();

    public WorldCatalog(List<Town> towns, List<Ground> grounds) {
        this.towns = List.copyOf(towns);
        this.grounds = List.copyOf(grounds);
        for (Town t : towns) {
            townById.put(t.id(), t);
        }
        for (Ground g : grounds) {
            groundById.put(g.id(), g);
            final int r = g.radius();
            for (int cx = Math.floorDiv(g.center().x() - r, CELL); cx <= Math.floorDiv(g.center().x() + r, CELL); cx++) {
                for (int cy = Math.floorDiv(g.center().y() - r, CELL); cy <= Math.floorDiv(g.center().y() + r, CELL); cy++) {
                    grid.computeIfAbsent(key(cx, cy), k -> new ArrayList<>()).add(g);
                }
            }
        }
    }

    private static long key(int cx, int cy) {
        return (((long) cx) << 32) ^ (cy & 0xffffffffL);
    }

    public List<Town> towns() {
        return towns;
    }

    public List<Ground> grounds() {
        return grounds;
    }

    public Town town(String id) {
        return townById.get(id);
    }

    public Ground ground(String id) {
        return groundById.get(id);
    }

    /** The town whose polygon (grown by {@code margin} around its centre test) contains the point, or null. */
    public Town townAt(Pos p, int margin) {
        for (Town t : towns) {
            if (t.center().distance2d(p) > (t.radius() + margin)) {
                continue;
            }
            if (t.contains(p.x(), p.y()) || (margin > 0 && (t.contains(p.x() + margin, p.y()) || t.contains(p.x() - margin, p.y()) || t.contains(p.x(), p.y() + margin) || t.contains(p.x(), p.y() - margin)))) {
                return t;
            }
        }
        return null;
    }

    /** Grounds whose edge is at most {@code reach} from the point, nearest edge first. */
    public List<Ground> groundsNear(Pos p, int reach) {
        final List<Ground> l = new ArrayList<>();
        for (int cx = Math.floorDiv(p.x() - reach, CELL); cx <= Math.floorDiv(p.x() + reach, CELL); cx++) {
            for (int cy = Math.floorDiv(p.y() - reach, CELL); cy <= Math.floorDiv(p.y() + reach, CELL); cy++) {
                for (Ground g : grid.getOrDefault(key(cx, cy), Collections.emptyList())) {
                    if (!l.contains(g) && ((g.center().distance2d(p) - g.radius()) <= reach) && (Math.abs(g.center().z() - p.z()) < 2500)) {
                        l.add(g);
                    }
                }
            }
        }
        l.sort((a, b) -> Double.compare(a.center().distance2d(p) - a.radius(), b.center().distance2d(p) - b.radius()));
        return l;
    }

    // ------------------------------------------------------------------ loading

    public static WorldCatalog load(Path file) throws Exception {
        try (InputStream in = Files.newInputStream(file)) {
            return load(in);
        }
    }

    public static WorldCatalog load(InputStream in) throws Exception {
        final DocumentBuilderFactory f = DocumentBuilderFactory.newInstance();
        f.setFeature("http://apache.org/xml/features/disallow-doctype-decl", true);
        final Document doc = f.newDocumentBuilder().parse(in);
        final List<Town> towns = new ArrayList<>();
        final NodeList tl = doc.getElementsByTagName("town");
        for (int i = 0; i < tl.getLength(); i++) {
            final Element e = (Element) tl.item(i);
            final String[] pts = text(e, "poly").trim().split("\\s+");
            final int[] px = new int[pts.length];
            final int[] py = new int[pts.length];
            for (int k = 0; k < pts.length; k++) {
                final String[] xy = pts[k].split(",");
                px[k] = Integer.parseInt(xy[0]);
                py[k] = Integer.parseInt(xy[1]);
            }
            final List<Assignment.Anchor> anchors = new ArrayList<>();
            final NodeList al = e.getElementsByTagName("anchor");
            for (int k = 0; k < al.getLength(); k++) {
                final Element a = (Element) al.item(k);
                anchors.add(new Assignment.Anchor(a.getAttribute("kind"), pos(a)));
            }
            towns.add(new Town(e.getAttribute("id"), e.getAttribute("name"), pos(e), num(e, "radius"), num(e, "minLevel"), num(e, "maxLevel"), px, py, List.copyOf(anchors)));
        }
        final List<Ground> grounds = new ArrayList<>();
        final NodeList gl = doc.getElementsByTagName("ground");
        for (int i = 0; i < gl.getLength(); i++) {
            final Element e = (Element) gl.item(i);
            final List<Pos> spots = new ArrayList<>();
            for (String s : text(e, "spots").trim().split("\\s+")) {
                final String[] xyz = s.split(",");
                spots.add(new Pos(Integer.parseInt(xyz[0]), Integer.parseInt(xyz[1]), Integer.parseInt(xyz[2])));
            }
            grounds.add(new Ground(e.getAttribute("id"), e.getAttribute("town"), pos(e), num(e, "radius"), num(e, "minLevel"), num(e, "maxLevel"), num(e, "monsters"),
                Double.parseDouble(e.getAttribute("aggressive")), Boolean.parseBoolean(e.getAttribute("indoor")), List.copyOf(spots)));
        }
        return new WorldCatalog(towns, grounds);
    }

    private static String text(Element e, String tag) {
        final NodeList l = e.getElementsByTagName(tag);
        return l.getLength() == 0 ? "" : l.item(0).getTextContent();
    }

    private static int num(Element e, String a) {
        return Integer.parseInt(e.getAttribute(a));
    }

    private static Pos pos(Element e) {
        return new Pos(num(e, "x"), num(e, "y"), num(e, "z"));
    }
}
